<script>
(function() {
  /* ========== Mobile hamburger menu ========== */
  var hamburger = document.getElementById('hamburger');
  var mobileNav = document.getElementById('mobileNav');

  hamburger.addEventListener('click', function() {
    var isOpen = mobileNav.classList.toggle('open');
    hamburger.classList.toggle('active', isOpen);
    hamburger.setAttribute('aria-expanded', isOpen);
    mobileNav.setAttribute('aria-hidden', !isOpen);
  });

  /* ========== Autocomplete dropdown ========== */
  var searchInput = document.getElementById('searchSpecialty');
  var dropdown = document.getElementById('autocompleteList');
  var items = dropdown.querySelectorAll('.autocomplete-item');
  var activeIndex = -1;

  function showDropdown() {
    dropdown.classList.add('visible');
    searchInput.setAttribute('aria-expanded', 'true');
  }

  function hideDropdown() {
    dropdown.classList.remove('visible');
    searchInput.setAttribute('aria-expanded', 'false');
    activeIndex = -1;
    updateActive();
  }

  function updateActive() {
    items.forEach(function(item, i) {
      item.classList.toggle('active', i === activeIndex);
      item.setAttribute('aria-selected', i === activeIndex ? 'true' : 'false');
    });
  }

  searchInput.addEventListener('focus', function() {
    if (searchInput.value.trim().length >= 0) showDropdown();
  });

  searchInput.addEventListener('input', function() {
    showDropdown();
    activeIndex = -1;
    updateActive();
  });

  searchInput.addEventListener('keydown', function(e) {
    var itemCount = items.length;
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      showDropdown();
      activeIndex = (activeIndex + 1) % itemCount;
      updateActive();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      showDropdown();
      activeIndex = activeIndex <= 0 ? itemCount - 1 : activeIndex - 1;
      updateActive();
    } else if (e.key === 'Enter') {
      if (activeIndex >= 0 && dropdown.classList.contains('visible')) {
        e.preventDefault();
        var activeItem = items[activeIndex];
        searchInput.value = activeItem.getAttribute('data-value') || '';
        hideDropdown();
      }
    } else if (e.key === 'Escape') {
      hideDropdown();
    }
  });

  items.forEach(function(item) {
    item.addEventListener('click', function() {
      searchInput.value = item.getAttribute('data-value') || '';
      hideDropdown();
      searchInput.focus();
    });
  });

  /* Close dropdown on outside click */
  document.addEventListener('click', function(e) {
    if (!searchInput.contains(e.target) && !dropdown.contains(e.target)) {
      hideDropdown();
    }
    // Close mobile nav on outside click
    if (!hamburger.contains(e.target) && !mobileNav.contains(e.target) && mobileNav.classList.contains('open')) {
      mobileNav.classList.remove('open');
      hamburger.classList.remove('active');
      hamburger.setAttribute('aria-expanded', 'false');
      mobileNav.setAttribute('aria-hidden', 'true');
    }
  });

  /* ========== Search form submit ========== */
  var searchForm = document.getElementById('searchForm');
  searchForm.addEventListener('submit', function(e) {
    e.preventDefault();
    var query = searchInput.value.trim();
    var location = document.getElementById('searchLocation').value.trim();
    var insurance = document.getElementById('searchInsurance').value;
    if (!query && !location) {
      searchInput.focus();
      return;
    }
    console.log('Search submitted:', { query: query, location: location, insurance: insurance });
  });

  /* ========== Specialty card clicks ========== */
  var specialtyCards = document.querySelectorAll('.specialty-card');
  specialtyCards.forEach(function(card) {
    card.addEventListener('click', function() {
      var specialty = card.getAttribute('data-specialty');
      console.log('Specialty selected:', specialty);
    });
  });

  /* ========== Mobile nav links dismiss drawer ========== */
  var mobileLinks = mobileNav.querySelectorAll('a');
  mobileLinks.forEach(function(link) {
    link.addEventListener('click', function() {
      mobileNav.classList.remove('open');
      hamburger.classList.remove('active');
      hamburger.setAttribute('aria-expanded', 'false');
      mobileNav.setAttribute('aria-hidden', 'true');
    });
  });
})();
</script>

</body>
